  "✨ Gitmek istediğiniz ülkeyi arayın... (Örn: Arnavutluk, Bosna Hersek, Japonya, Karadağ, Tayland...)": "✨ Найдите любое место для изучения... (например, Албания, Босния, Япония, Черногория, Таиланд...)",
