  "Search city, country, or vibe (e.g. Chiang Mai, Bali, surfing, Tbilisi, 0% tax, DTV...)": "Найдите город, страну или атмосферу (например, Чиангмай, Бали, серфинг, Тбилиси, налог 0 %, цифровое телевидение...)",
