  "${getCountryName(currentPassport, language)} vatandaşları yurt dışında pasaport kaybı, tutuklanma, doğal afet, kaza veya acil tahliye durumlarında bu hattan 7 gün 24 saat doğrudan destek alabilir.": "Граждане ${getCountryName(currentPassport, language)} могут напрямую получить доступ к круглосуточной консульской защите за рубежом в случае утери паспорта, задержания, несчастных случаев или кризисной эвакуации.",
