  "Planlanan rotanız, önceki seyahatleriniz ile birlikte değerlendirildiğinde herhangi bir 180 günlük kayan dönemde 90 gün sınırını aşmaktadır (Pik: ${routeSummary.schengenAnalysis.peak180Days} gün). Bu rota vize ihlaline yol açabilir; lütfen durak sürelerini kısaltın.": "Ваш запланированный маршрут превышает 90-дневный порог в течение скользящих 180-дневных периодов, если оценивать его с учетом предыдущих поездок (пик: ${routeSummary.schengenAnalysis.peak180Days} дней). Это может спровоцировать визовые нарушения; рассмотреть возможность сокращения срока пребывания.",
  "Your planned route exceeds the 90-day threshold across rolling 180-day periods when evaluated with prior trips (Peak: ${routeSummary.schengenAnalysis.peak180Days} days). This may trigger visa violations; consider shortening stays.": "Ваш запланированный маршрут превышает 90-дневный порог в течение скользящих 180-дневных периодов, если оценивать его с учетом предыдущих поездок (пик: ${routeSummary.schengenAnalysis.peak180Days} дней). Это может спровоцировать визовые нарушения; рассмотреть возможность сокращения срока пребывания.",
