  "Seçilen filtrelere uyan destinasyon bulunamadı. Lütfen giriş türü veya gün sınırını esnetin.": "Не найдено направлений, соответствующих вашим фильтрам. Попробуйте выбрать больше типов въездов или уменьшить лимит пребывания.",
  "No destinations found matching your filters. Try selecting more entry types or relaxing the stay limit.": "Не найдено направлений, соответствующих вашим фильтрам. Попробуйте выбрать больше типов въездов или уменьшить лимит пребывания.",
