  "Sabahın erken saatlerinde kalabalıklar başlamadan Sultanahmet ve Ayasofya’yı gezin.": "Совершите экскурсию по собору Святой Софии и Голубой мечети рано утром, до прибытия туристических автобусов.",
  "Tour Hagia Sophia and Blue Mosque early morning before tour buses arrive.": "Совершите экскурсию по собору Святой Софии и Голубой мечети рано утром, до прибытия туристических автобусов.",
