  "Wander the subterranean glow of Basilica Cistern and Topkapi Palace chambers.": "Прогуляйтесь по подземному сиянию Цистерны Базилики и покоев дворца Топкапы.",
  "Eminönü’nden Kadıköy veya Üsküdar’a şehir hatları vapuruyla geçerek martılara simit atın ve Boğaz rüzgarını hissedin.": "Сядьте на общественный пригородный паром через Босфор до Кадыкея и покормите симит-чаек.",
  "Board a public commuter ferry across the Bosphorus to Kadikoy while feeding seagulls simit.": "Сядьте на общественный пригородный паром через Босфор до Кадыкея и покормите симит-чаек.",
