  "Geleceğin neon ışıklı metropolü Tokyo’dan başlayıp Fuji Dağı eteklerindeki kaplıcalara, Kyoto’nun bin yıllık Zen tapınaklarından Osaka’nın efsanevi sokak lezzetlerine uzanan 10 günlük kusursuz rota.": "10-дневный маршрут мастер-класса, соединяющий гиперсовременный Токио, горячие источники Фудзи в Хаконэ, тысячелетние святыни в Киото, кланяющиеся олени в Наре и кулинарные изыски Осакана.",
  "A 10-day masterclass itinerary linking hypermodern Tokyo, Fuji hot springs at Hakone, thousand-year-old shrines in Kyoto, bowing deer in Nara, and Osakan culinary indulgence.": "10-дневный маршрут мастер-класса, соединяющий гиперсовременный Токио, горячие источники Фудзи в Хаконэ, тысячелетние святыни в Киото, кланяющиеся олени в Наре и кулинарные изыски Осакана.",
