  "Roma Termini istasyonu, Kolezyum çevresi ve metro hatlarında bilet makinelerinde yardım bahanesiyle yaklaşanlara ve yankesicilere prim vermeyin.": "Остерегайтесь карманников в переполненных поездах римского метро и вокруг вокзала Термини.",
  "Beware of pickpockets on crowded Rome Metro trains and around Termini station.": "Остерегайтесь карманников в переполненных поездах римского метро и вокруг вокзала Термини.",
  "Kolezyum çevresindeki gladyatör kostümlü kişilerle fotoğraf çektirmeyin; sonrasında zorla 20-50€ talep ederler.": "Не позируйте с костюмированными гладиаторами возле Колизея, поскольку они агрессивно требуют денег.",
  "Avoid posing with costume gladiators outside the Colosseum as they aggressively demand cash.": "Не позируйте с костюмированными гладиаторами возле Колизея, поскольку они агрессивно требуют денег.",
  "Restoranlarda fahiş fiyatlardan kaçınmak için turistik anıtların 2 sokak arkasındaki trattoriaları tercih edin.": "Ешьте в 2–3 кварталах от основных памятников, чтобы насладиться превосходной едой и честными ценами.",
  "Eat 2-3 blocks away from major monuments for superior food and honest prices.": "Ешьте в 2–3 кварталах от основных памятников, чтобы насладиться превосходной едой и честными ценами.",
  "Işıklar Şehri & Fransız Rivierası: Paris, Şatolar & Nice / Monaco": "Город света и Французская Ривьера: Париж, замки и Ницца / Монако",
  "City of Light & French Riviera: Paris, Châteaux & Nice / Monaco": "Город света и Французская Ривьера: Париж, замки и Ницца / Монако",
  "Paris’in dünyaca ünlü anıtları ve sanat müzelerinden başlayıp görkemli Versay Sarayı’na, ardından güneye inerek Akdeniz kıyılarındaki Nice ve Monaco’nun zarafetine uzanan 9 günlük unutulmaz gezi.": "9-дневное путешествие по Франции, сочетающее романтические бульвары и музеи Парижа с величием Версаля, за которым следует залитое солнцем гламур Ниццы и Лазурного берега.",
  "A 9-day French journey pairing the romantic boulevards and museums of Paris with Versailles grandeur, followed by the sun-drenched glamor of Nice and the Côte d’Azur.": "9-дневное путешествие по Франции, сочетающее романтические бульвары и музеи Парижа с величием Версаля, за которым следует залитое солнцем гламур Ниццы и Лазурного берега.",
