  "Müze girişleri için dijital biletler": "Билеты в музеи оффлайн на телефоне",
  "Offline museum tickets on phone": "Билеты в музеи оффлайн на телефоне",
  "Bir dükkana veya restorana girerken mutlaka \"Bonjour\" (günaydın) ve çıkarken \"Au revoir\" (hoşça kalın) deyin; bu kurala uymamak kabalık sayılır.": "Всегда приветствуйте владельцев магазинов и официантов вежливым «Добрый день» при входе; это фундаментальный этикет.",
  "Always greet shopkeepers and waiters with a polite \"Bonjour\" when entering; it is fundamental etiquette.": "Всегда приветствуйте владельцев магазинов и официантов вежливым «Добрый день» при входе; это фундаментальный этикет.",
  "Paris Metrosunda hoparlörle müzik dinlemek veya yüksek sesle konuşmak hoş karşılanmaz.": "В парижском метро держите сумку застегнутой на молнии и перед собой.",
  "Keep your bag zipped and in front of you on the Paris Metro.": "В парижском метро держите сумку застегнутой на молнии и перед собой.",
  "Gare du Nord ve Châtelet aktarma istasyonlarında çantanızı önünüzde tutun.": "Никогда не оставляйте телефоны или солнцезащитные очки на столиках в ресторане, обращенных к оживленным тротуарам.",
  "Never leave phones or sunglasses on restaurant tables facing busy sidewalks.": "Никогда не оставляйте телефоны или солнцезащитные очки на столиках в ресторане, обращенных к оживленным тротуарам.",
  "Tapınaklar, Dağlar & Zümrüt Adalar: Bangkok, Chiang Mai & Phuket / Phi Phi": "Храмы, горы и изумрудные острова: Бангкок, Чиангмай и Пхукет/Пхи-Пхи",
  "Temples, Mountains & Emerald Islands: Bangkok, Chiang Mai & Phuket / Phi Phi": "Храмы, горы и изумрудные острова: Бангкок, Чиангмай и Пхукет/Пхи-Пхи",
  "Bangkok’un altın yaldızlı tapınakları ve sokak lezzetlerinden başlayıp kuzeyin sisli dağları ve fil koruma alanlarına sahip Chiang Mai’ye, oradan da güneyin masalsı zümrüt sularına uzanan 10 günlük Tayland macerası.": "10-дневное тропическое погружение от священных храмов Бангкока и лодочной лапши до северной культуры и этических слоновьих заповедников в Чиангмае, завершающееся в бирюзовых водах Андаманского моря.",
  "A 10-day tropical immersion from Bangkok’s sacred temples and boat noodles, to northern culture and ethical elephant sanctuaries in Chiang Mai, concluding in Andaman turquoise waters.": "10-дневное тропическое погружение от священных храмов Бангкока и лодочной лапши до северной культуры и этических слоновьих заповедников в Чиангмае, завершающееся в бирюзовых водах Андаманского моря.",
