  "Tayland’da bahşiş zorunlu bir gelenek olmasa da, turistik mekanlarda ve iyi servis aldığınızda %10 veya bozuk paraları bırakmak memnuniyetle karşılanır.": "Чаевые не являются традиционными в местной тайской культуре, но в ресторанах, ориентированных на туристов, принято давать чаевые в размере 10%.",
