  "Kraliyet ailesi hakkında herhangi bir eleştiri veya saygısızlık çok ağır hapis cezasıyla sonuçlanır (Lèse-majesté yasası).": "Строгие законы об оскорблении величества защищают монархию; никогда не высказывайтесь критически о роялти и не портите валюту.",
  "Strict Lèse-majesté laws protect the Monarchy; never speak critically of royalty or deface currency.": "Строгие законы об оскорблении величества защищают монархию; никогда не высказывайтесь критически о роялти и не портите валюту.",
  "Birinin başına veya saçına asla dokunmayın; baş kutsal kabul edilir. Ayak tabanınızı kimseye veya kutsal heykellere doğru uzatmayın.": "Никогда не трогайте никого по голове и не направляйте ноги в сторону людей или статуй Будды.",
  "Never touch anyone on the head or point your feet toward people or Buddha statues.": "Никогда не трогайте никого по голове и не направляйте ноги в сторону людей или статуй Будды.",
  "Sokaklarda musluk suyu ASLA içilmez; daima mühürlü şişe su tüketin.": "Никогда не пейте водопроводную воду; всегда употребляйте запечатанную бутилированную воду или фильтрованный лед.",
  "Never drink tap water; always consume sealed bottled water or filtered ice.": "Никогда не пейте водопроводную воду; всегда употребляйте запечатанную бутилированную воду или фильтрованный лед.",
  "Ateş ve Buz Ülkesi: 1 No’lu Çevre Yolu (Ring Road) & Güney Sahili": "Земля огня и льда: кольцевая дорога № 1 и экспедиция на южное побережье",
  "Land of Fire & Ice: Route 1 Ring Road & South Coast Expedition": "Земля огня и льда: кольцевая дорога № 1 и экспедиция на южное побережье",
  "Reykjavik’ten başlayıp devasa şelalelere, siyah kumsallara, mavi buzul lagünlerine ve jeotermal kaplıcalara uzanan 8 günlük unutulmaz bir kutup ve doğa macerası.": "8-дневное субарктическое путешествие вокруг вулканических чудес, громыхающих водопадов, черных песков Рейнисфьяра и плавающих айсбергов в ледниковой лагуне Йокульсарлон.",
  "An 8-day subarctic road trip circling volcanic wonders, thundering waterfalls, Reynisfjara black sands, and floating icebergs at Jokulsarlon glacier lagoon.": "8-дневное субарктическое путешествие вокруг вулканических чудес, громыхающих водопадов, черных песков Рейнисфьяра и плавающих айсбергов в ледниковой лагуне Йокульсарлон.",
