  "Ride the elevator up Hallgrimskirkja tower for iconic views over colorful Reykjavik roofs.": "Поднимитесь на лифте на башню Хатльгримскиркья, чтобы полюбоваться потрясающими видами на красочные крыши Рейкьявика.",
