  "Su geçirmez montunuzu giyip Seljalandsfoss şelalesinin döküldüğü su perdesinin arkasındaki mağaradan geçin.": "Наденьте полную водонепроницаемую экипировку и отправляйтесь в поход за грохотом Сельяландсфосса.",
  "Slip into full waterproof gear and hike behind the crashing veil of Seljalandsfoss.": "Наденьте полную водонепроницаемую экипировку и отправляйтесь в поход за грохотом Сельяландсфосса.",
  "Skogafoss’un tepesindeki seyir platformuna 500 basamak tırmanın.": "Поднимитесь на 500 ступенек на верхнюю смотровую площадку над грозным Скогафоссом.",
  "Climb 500 steps to the top observation deck over thunderous Skogafoss.": "Поднимитесь на 500 ступенек на верхнюю смотровую площадку над грозным Скогафоссом.",
  "Reynisfjara siyah kumlu plajında devasa heksagonal bazalt sütunları önünde fotoğraf çekilin.": "Полюбуйтесь высокими базальтовыми колоннами, возвышающимися из черного вулканического песка в Рейнисфьяре.",
  "Admire the towering basalt columns rising out of black volcanic sand at Reynisfjara.": "Полюбуйтесь высокими базальтовыми колоннами, возвышающимися из черного вулканического песка в Рейнисфьяре.",
  "Vik kasabasında taze morina balığı (Fish & Chips)": "Свежая рыба и чипсы из атлантической трески в деревне Вик",
  "Fresh Atlantic cod fish and chips in Vík village": "Свежая рыба и чипсы из атлантической трески в деревне Вик",
  "Fırında füme kuzu budu": "Голяшка исландского ягненка медленного копчения",
  "Slow-smoked Icelandic lamb shank": "Голяшка исландского ягненка медленного копчения",
  "İzlanda çavdar ekmeği (Rúgbrauð)": "Темный ржаной хлеб, выпеченный геотермальным способом (Rúgbrauð)",
