  "Skaftafell & Svartifoss Basalt Waterfall": "Скафтафетль и базальтовый водопад Свартифосс",
  "Amfibi araç veya zodyak botla Jökulsárlón lagününde dev buz kütleleri ve fok balıkları arasında dolaşın.": "Сядьте на лодку-амфибию среди ярко-голубых айсбергов и игривых тюленей в Йокульсарлоне.",
  "Board an amphibious boat among electric-blue icebergs and playful seals in Jokulsarlon.": "Сядьте на лодку-амфибию среди ярко-голубых айсбергов и игривых тюленей в Йокульсарлоне.",
  "Karşı kıyıdaki Diamond Beach’te siyah volkanik kum üzerinde güneş gibi parıldayan pırlanta berraklığındaki buz parçalarına dokunun.": "Прогуляйтесь по Даймонд-Бич, любуясь алмазоподобными кусками ледникового льда, выброшенными на берег.",
  "Walk across Diamond Beach admiring diamond-like chunks of glacial ice washed ashore.": "Прогуляйтесь по Даймонд-Бич, любуясь алмазоподобными кусками ледникового льда, выброшенными на берег.",
  "Kramponlarınızı takıp profesyonel rehber eşliğinde Avrupa’nın en büyük buzulu Vatnajökull üzerinde yürüyün.": "Наденьте кошки и отправляйтесь в поход по усеянной трещинами ледяной шапке Ватнайёкюдль.",
  "Strap on crampons for a guided trek across the crevasse-strewn Vatnajokull ice cap.": "Наденьте кошки и отправляйтесь в поход по усеянной трещинами ледяной шапке Ватнайёкюдль.",
