  "Buzul yürüyüşü ve buz mağarası turlarına ASLA tek başınıza gitmeyin; derin yarıklar ölümcüldür, lisanslı rehber zorunludur.": "Никогда не отправляйтесь на ледники без сертифицированных гидов; глубокие расщелины скрыты и смертоносны.",
  "Never venture onto glaciers without certified guides; deep crevasses are hidden and deadly.": "Никогда не отправляйтесь на ледники без сертифицированных гидов; глубокие расщелины скрыты и смертоносны.",
  "Hava durumunu ve yol durumunu her sabah road.is ve vedur.is sitelerinden kontrol edin; ani fırtınalarda yollar kapanabilir.": "Ежедневно проверяйте дорожную ситуацию на сайтах road.is и vedur.is; Сильный ураганный ветер может внезапно перекрыть шоссе.",
  "Check road conditions daily on road.is and vedur.is; severe gale winds can close highways suddenly.": "Ежедневно проверяйте дорожную ситуацию на сайтах road.is и vedur.is; Сильный ураганный ветер может внезапно перекрыть шоссе.",
