  "Bilekli sağlam yürüyüş botu": "Прочные походные ботинки с высоким голенищем и глубоким протектором.",
  "Sturdy high-ankle hiking boots with deep tread": "Прочные походные ботинки с высоким голенищем и глубоким протектором.",
  "Termal kaplıcalar için mayo ve havlu": "Купальник и быстросохнущее полотенце для геотермальных лагун.",
  "Swimsuit and quick-dry towel for geothermal lagoons": "Купальник и быстросохнущее полотенце для геотермальных лагун.",
  "İzlanda’da off-road (yol dışı) araç kullanmak kesinlikle yasaktır ve doğaya verilen kalıcı zarar nedeniyle astronomik para cezası uygulanır.": "Вождение по бездорожью в Исландии строго запрещено и влечет за собой огромные штрафы за защиту нежного мха.",
  "Off-road driving is strictly illegal in Iceland and carries massive fines to protect delicate moss.": "Вождение по бездорожью в Исландии строго запрещено и влечет за собой огромные штрафы за защиту нежного мха.",
  "Hava aniden değişebilir; kapı açarken aracın kapısını iki elinizle tutun, şiddetli fırtınalarda kapılar ters dönebilir.": "При открытии придерживайте двери автомобиля обеими руками; Сильные порывы ветра часто срывают двери автомобилей с петель.",
  "Hold car doors with both hands when opening; extreme wind gusts frequently rip car doors off hinges.": "При открытии придерживайте двери автомобиля обеими руками; Сильные порывы ветра часто срывают двери автомобилей с петель.",
  "Ülkede organize suç veya taksi dolandırıcılığı yoktur; en büyük tehlike ekstrem doğa koşullarıdır.": "Жестоких преступлений практически нет; Стихийные бедствия и погода — ваши единственные проблемы безопасности.",
  "There is virtually zero violent crime; natural hazards and weather are your only safety concerns.": "Жестоких преступлений практически нет; Стихийные бедствия и погода — ваши единственные проблемы безопасности.",
  "Almanya Masal & Tarih Rotası: Berlin, Romantik Yol & Bavyera Alpleri": "Сказка и наследие Германии: Берлин, романтическая дорога и Баварские Альпы",
  "Fairy Tale & Heritage Germany: Berlin, Romantic Road & Bavarian Alps": "Сказка и наследие Германии: Берлин, романтическая дорога и Баварские Альпы",
  "Tarihi Berlin Duvarı ve müzeler adasından başlayıp Orta Çağ kasabalarıyla ünlü Romantik Yol’a, oradan da Neuschwanstein Şatosu ve Münih bira bahçelerine uzanan 9 günlük klasik rota.": "9-дневный гранд-тур по Германии из оживленного культурного центра Берлина через сказочные средневековые города вдоль Романтической дороги к замку Нойшванштайн и Мюнхену.",
  "A 9-day German grand tour from the vibrant cultural center of Berlin through fairytale medieval towns along the Romantic Road to Neuschwanstein Castle and Munich.": "9-дневный гранд-тур по Германии из оживленного культурного центра Берлина через сказочные средневековые города вдоль Романтической дороги к замку Нойшванштайн и Мюнхену.",
