  "Reichstag kubbe ziyareti ücretsizdir fakat haftalar öncesinden resmi web sitesinden pasaportla kayıt yaptırmak ZORUNLUDUR.": "Вход на купол Рейхстага бесплатный, но требует обязательной регистрации паспорта онлайн за несколько недель вперед.",
  "Reichstag dome entry is free but requires mandatory passport registration online weeks ahead.": "Вход на купол Рейхстага бесплатный, но требует обязательной регистрации паспорта онлайн за несколько недель вперед.",
