  "Almanya’da restoranlarda hesaba %5-10 civarı bahşiş (Trinkgeld) eklemek gelenektir. Ödeme yaparken para üstü beklemeden doğrudan toplam tutarı söyleyerek yuvarlarsınız (örn. hesap 27€ ise \"30€ bitte\" dersiniz).": "Чаевые в размере 5-10% являются стандартными. Вместо того, чтобы оставлять наличные на столах, при оплате сообщите серверу округленную сумму.",
