  "Trafik ışıklarında yayalar için kırmızı yanarken ASLA karşıya geçmeyin; çocuklar varsa sert tepki alırsınız.": "Никогда не переходите дорогу на красный свет; Немцы серьезно относятся к правилам пешеходного движения, особенно в отношении детей.",
  "Never jaywalk on red lights; Germans take pedestrian rules seriously, especially around children.": "Никогда не переходите дорогу на красный свет; Немцы серьезно относятся к правилам пешеходного движения, особенно в отношении детей.",
  "Bisiklet yollarında (Radweg) yürümeyin; bisikletliler hızlı gelir ve haklı olarak zil çalarlar.": "Не ходите по велосипедным дорожкам с красным покрытием (Радвег); велосипедисты едут быстро.",
  "Do not walk on red-paved cycle paths (Radweg); cyclists ride fast.": "Не ходите по велосипедным дорожкам с красным покрытием (Радвег); велосипедисты едут быстро.",
  "Geri dönüşümlü şişeleri çöpe atmayın; marketlerdeki otomatlara iade edip 0.25€ depozito alınır.": "Не выбрасывайте депозитные бутылки (Пфанд) в мусорные баки; верните их в автоматы супермаркета за 0,25 евро.",
  "Do not throw deposit bottles (Pfand) in trash cans; return them to supermarket machines for €0.25.": "Не выбрасывайте депозитные бутылки (Пфанд) в мусорные баки; верните их в автоматы супермаркета за 0,25 евро.",
