  "Kraliyet başkenti Madrid’den başlayıp flamenko ve portakal çiçeği kokulu Sevilla’ya, Elhamra Sarayı’nın Mağribi büyüsüne ve Akdeniz’in Gaudi mimarili incisi Barselona’ya uzanan 10 günlük masalsı rota.": "10-дневное яркое путешествие, соединяющее королевские площади Мадрида, зажигательное фламенко Севильи, мавританский дворец Альгамбра в Гранаде и Барселону Гауди.",
