  "Tahran’ın saraylarından başlayarak Şah Abbas’ın \"Dünyanın Yarısı\" İsfahan’ına, çölün kerpiç başkenti Yezd’den 2.500 yıllık Persepolis ve şairler kenti Şiraz’a uzanan 9 günlük büyüleyici Pers kültür yolculuğu.": "Легендарное 9-дневное культурное путешествие по Ирану: от королевских дворцов Каджаров в Тегеране до бирюзовых куполов Исфахана, сырцовых пустынных переулков в Йезде и 2500-летних руин Персеполя в Ширазе.",
  "A legendary 9-day cultural journey through Iran: from royal Qajar palaces in Tehran to the turquoise domes of Isfahan, mudbrick desert alleys in Yazd, and 2,500-year-old Persepolis ruins in Shiraz.": "Легендарное 9-дневное культурное путешествие по Ирану: от королевских дворцов Каджаров в Тегеране до бирюзовых куполов Исфахана, сырцовых пустынных переулков в Йезде и 2500-летних руин Персеполя в Ширазе.",
