  "3 Days (UNESCO Square, bridges & palaces)": "3 дня (площадь ЮНЕСКО, мосты и дворцы)",
  "Nakş-ı Cihan Meydanı (Dünyanın en görkemli tarihi meydanlarından)": "Площадь Накш-э Джахан (одна из крупнейших общественных площадей на Земле)",
  "Naqsh-e Jahan Square (One of the largest public squares on Earth)": "Площадь Накш-э Джахан (одна из крупнейших общественных площадей на Земле)",
