  "Göbeklitepe ile başlayan 12.000 yıllık medeniyetler beşiği. Hitit, Grek, Roma, Bizans ve Osmanlı İmparatorlukları sonrasında 1923’te Mustafa Kemal Atatürk önderliğinde modern Türkiye Cumhuriyeti kuruldu.": "Колыбель цивилизаций, насчитывающих 12 000 лет, в Гобекли-Тепе. Дом Хеттской, Римской, Византийской и Османской империй, основанный как современная республика в 1923 году Мустафой Кемалем Ататюрком.",
  "Cradle of civilizations spanning 12,000 years from Gobekli Tepe. Home to Hittite, Roman, Byzantine, and Ottoman Empires, founded as a modern Republic in 1923 by Mustafa Kemal Atatürk.": "Колыбель цивилизаций, насчитывающих 12 000 лет, в Гобекли-Тепе. Дом Хеттской, Римской, Византийской и Османской империй, основанный как современная республика в 1923 году Мустафой Кемалем Ататюрком.",
