  "TGV (hızlı tren) ile Paris’ten Lyon, Marsilya ve Bordeaux’ya 2 saatte ulaşın; metro için Île-de-France Navigo Pass kullanın.": "Используйте скоростные поезда TGV по городам; получите проездной билет Иль-де-Франс на парижское метро.",
  "Use high-speed TGV trains across cities; get an Île-de-France transport pass for Paris Metro.": "Используйте скоростные поезда TGV по городам; получите проездной билет Иль-де-Франс на парижское метро.",
  "Katolik Hristiyan (~%47), Seküler / Dinsiz (~%40), Müslüman (~%9), Musevi (~%1).": "Католик-христианин (~47%), светский/нерелигиозный (~40%), мусульманин (~9%), иудей (~1%).",
  "Catholic Christian (~47%), Secular / Non-religious (~40%), Muslim (~9%), Jewish (~1%).": "Католик-христианин (~47%), светский/нерелигиозный (~40%), мусульманин (~9%), иудей (~1%).",
  "Laiklik (Laïcité) devletin temel ilkesidir. Katedrallerde sessizlik korunmalı, şapkalar çıkarılmalıdır.": "Государственный секуляризм (Laïcité) является конституционным. Соблюдайте тишину и почтительную одежду в исторических соборах.",
