  "Fransızca (Français). Şehirlerde ve genç nesilde İngilizce bilinir ancak önce Fransızca selamlaşmak büyük saygı görür.": "Французский (Français). В отелях и городах говорят на английском, но начало с «Bonjour» меняет все.",
  "French (Français). English is spoken in hotels and cities, but starting with \"Bonjour\" changes everything.": "Французский (Français). В отелях и городах говорят на английском, но начало с «Bonjour» меняет все.",
