  "Galyalılar ve Şarlman’dan başlayıp 1789 Fransız İhtilali ile \"Özgürlük, Eşitlik, Kardeşlik\" ilkelerini dünyaya yayan cumhuriyet. Aydınlanma felsefesi ve sanatın global başkenti.": "От Римской Галлии и Карла Великого до Французской революции 1789 года, провозгласившей «Свободу, равенство, братство». Мировая колыбель Просвещения, кино и высокой культуры.",
  "From Roman Gaul and Charlemagne to the 1789 French Revolution proclaiming \"Liberté, Égalité, Fraternité.\" Global cradle of Enlightenment, cinema, and haute culture.": "От Римской Галлии и Карла Великого до Французской революции 1789 года, провозгласившей «Свободу, равенство, братство». Мировая колыбель Просвещения, кино и высокой культуры.",
