  "\"La Dolce Vita\" (The Sweet Life); long family lunches, evening plaza strolls (passeggiata), espresso bars, and passionate craftsmanship.": "«Ла Дольче Вита» (Сладкая жизнь); длинные семейные обеды, вечерние прогулки по площади (passeggiata), эспрессо-бары и страстное мастерство.",
