  "April - June and September - October for sightseeing; avoid August heatwaves when many family shops close.": "апрель-июнь и сентябрь-октябрь для осмотра достопримечательностей; избегайте августовской жары, когда многие семейные магазины закрываются.",
  "Frecciarossa ve Italo hızlı trenleri Roma, Floransa, Venedik ve Milano arasında en konforlu yoldur; biletleri önceden alın.": "Сядьте на скоростной поезд Frecciarossa между Римом, Флоренцией, Венецией и Миланом; бронируйте билеты в музеи заранее онлайн.",
  "Take Frecciarossa high-speed trains between Rome, Florence, Venice, and Milan; book museum tickets online in advance.": "Сядьте на скоростной поезд Frecciarossa между Римом, Флоренцией, Венецией и Миланом; бронируйте билеты в музеи заранее онлайн.",
  "Katolik Hristiyan (~%79, Vatikan’a ev sahipliği yapar), Dinsiz / Seküler (~%16), Müslüman (~%3).": "Римско-католические (~79%, вокруг Святого Престола Ватикана), нерелигиозные (~16%), мусульмане (~3%).",
  "Roman Catholic (~79%, surrounding the Vatican City Holy See), Non-religious (~16%), Muslim (~3%).": "Римско-католические (~79%, вокруг Святого Престола Ватикана), нерелигиозные (~16%), мусульмане (~3%).",
  "Vatikan ve tüm kiliselerde sıkı kıyafet kontrolü vardır; kolsuz tişört ve şortla girişe izin verilmez.": "В церквях строгий дресс-код: никаких обнаженных плеч, коротких шорт и глубоких вырезов.",
  "Strict dress code in churches: no bare shoulders, short shorts, or plunging necklines.": "В церквях строгий дресс-код: никаких обнаженных плеч, коротких шорт и глубоких вырезов.",
