  "Italian (Italiano). English is spoken in hotels and restaurants in Rome, Florence, and Milan.": "Итальянский (Italiano). На английском говорят в отелях и ресторанах Рима, Флоренции и Милана.",
  "Büyük şehirlerde ve otellerde iyi; güney köylerinde ve yerel pazarlarda jestler ve beden dili kullanılır.": "Хорошо в основных городах; базовый в южных деревнях, где выразительные жесты устраняют разрыв.",
