  "Roma İmparatorluğu’nun başkenti, Rönesans’ın doğduğu topraklar. Da Vinci, Michelangelo ve Dante ile Batı sanat ve hukukunun temellerini attı; 1861 Risorgimento ile birleşti.": "Столица Римской империи и место зарождения эпохи Возрождения. Дом Микеланджело, Леонардо да Винчи и Данте, объединенный в современную Италию в 1861 году.",
  "Seat of the Roman Empire and the birthplace of the Renaissance. Home to Michelangelo, Leonardo da Vinci, and Dante, unified into modern Italy in 1861.": "Столица Римской империи и место зарождения эпохи Возрождения. Дом Микеланджело, Леонардо да Винчи и Данте, объединенный в современную Италию в 1861 году.",
