  "Açık hava, canlı gece hayatı, aile bağları ve \"sobremesa\" (yemek sonrası saatlerce süren masa başı sohbeti).": "Яркая уличная жизнь на открытом воздухе, оживленные поздние ночи, семейное тепло и традиция «собремеса» (продолжительный разговор после еды).",
  "Vibrant outdoor street life, lively late nights, family warmth, and the tradition of \"sobremesa\" (lingering conversation after a meal).": "Яркая уличная жизнь на открытом воздухе, оживленные поздние ночи, семейное тепло и традиция «собремеса» (продолжительный разговор после еды).",
