  "Kart ve temassız ödeme son derece yaygındır (%95). Plaj büfelerinde veya küçük pazarlarda az miktar nakit Euro faydalıdır.": "Прием карт высок; бесконтактная оплата принимается во всех магазинах и тапас-барах.",
  "Card acceptance is high; contactless payment is accepted across shops and tapas bars.": "Прием карт высок; бесконтактная оплата принимается во всех магазинах и тапас-барах.",
  "Turizm, inşaat, otomotiv montajı, yenilenebilir enerji ve tarımsal zeytinyağı ihracatı.": "Туризм, автомобилестроение, возобновляемая энергетика и экспорт оливкового масла (мировой лидер №1).",
  "Tourism, automotive assembly, renewable energy, and olive oil export (world #1 producer).": "Туризм, автомобилестроение, возобновляемая энергетика и экспорт оливкового масла (мировой лидер №1).",
  "Bahşiş zorunlu değildir. Barda veya kafede para üstünden kalan bozuklukları (0.50 - 2 €) tabakta bırakmak adettendir.": "Чаевые строго добровольны; в тапас-барах принято оставлять мелкую сдачу (от 0,50 до 2 €).",
  "Tipping is strictly voluntary; leaving small change (€0.50 to €2) at casual tapas bars is customary.": "Чаевые строго добровольны; в тапас-барах принято оставлять мелкую сдачу (от 0,50 до 2 €).",
  "Kuyruğa girmek (Queueing) kutsal bir kuraldır; sıraya kaynak yapmak en büyük ayıptır.": "Очередь — священный институт; никогда не вставайте в очередь ни при каких обстоятельствах.",
  "Queueing is a sacred institution; never jump a queue under any circumstances.": "Очередь — священный институт; никогда не вставайте в очередь ни при каких обстоятельствах.",
  "\"Please\", \"Thank you\" ve \"Sorry\" kelimeleri gün boyu durmaksızın kullanılır.": "Слова «Please» (пожалуйста), «Thank you» (спасибо) и «Sorry» (извините) звучат почти в каждом предложении.",
  "\"Please\", \"Thank you\", and \"Sorry\" are woven into nearly every sentence.": "Слова «Please» (пожалуйста), «Thank you» (спасибо) и «Sorry» (извините) звучат почти в каждом предложении.",
  "Metro yürüyen merdivenlerinde DAİMA sağda durulur, sol taraf yürüyenlere bırakılır.": "На эскалаторах лондонского метро ВСЕГДА стойте справа; левая сторона строго для идущих.",
  "Always stand on the right on Tube escalators; the left is strictly for walking.": "На эскалаторах лондонского метро ВСЕГДА стойте справа; левая сторона строго для идущих.",
  "Pub kültürü: Sipariş masaya verilmez; bara gidilip içecekler bizzat alınır ve anında ödenir.": "Культура пабов: заказ у столика не принимается; напитки заказывают, получают и оплачивают прямо у барной стойки.",
  "In pubs, you order and pay directly at the bar counter, not from your table.": "Культура пабов: заказ у столика не принимается; напитки заказывают, получают и оплачивают прямо у барной стойки.",
