  "Londra içinde temasız kredi kartınızı veya telefonunuzu doğrudan metro turnikesine okutun (Oyster kart almanıza gerek yoktur).": "Прикладывайте бесконтактную карту или смартфон на входе и выходе в лондонском метро.",
  "Tap in and out on the London Underground using your contactless bank card or phone.": "Прикладывайте бесконтактную карту или смартфон на входе и выходе в лондонском метро.",
  "Hristiyanlık (~%46, Anglikan Kilisesi ve Katolik), Dinsiz / Seküler (~%37), Müslüman (~%6.5), Hindu (~%1.7).": "Христианство (~46%, Церковь Англии и католицизм), нерелигиозные (~37%), мусульмане (~6,5%), индуисты (~1,7%).",
