  "1215 Magna Carta ile hukukun üstünlüğünü başlatan, Sanayi Devrimi’ni doğuran ada ülkesi. Üzerinde güneş batmayan imparatorluktan modern finans, popüler kültür ve bilim merkezine dönüştü.": "Родина парламентской демократии (Великая хартия вольностей 1215 г.) и промышленной революции. Прошла путь от мировой империи до глобального финансового, научного и культурного центра.",
