  "Late March - May (Cherry blossoms) and October - November (Autumn foliage) are ideal.": "Конец марта — май (сакура) и октябрь — ноябрь (осенние клены момидзи) — самые живописные сезоны.",
  "Telefona dijital Suica/Pasmo kartı yükleyin; tüm tren ve otobüslerde dokunup geçin.": "Добавьте цифровую карту Suica или Pasmo в Apple/Google Wallet для удобного проезда в поездах и метро.",
  "Add digital Suica/Pasmo card to Apple/Google Wallet for seamless train rides.": "Добавьте цифровую карту Suica или Pasmo в Apple/Google Wallet для удобного проезда в поездах и метро.",
  "Şintoizm (~%48) ve Budizm (~%46) senkretik bir uyumla bir arada yaşanır.": "Синтоизм (~48%) и буддизм (~46%) гармонично сосуществуют в повседневной жизни.",
  "Shinto (~48%) and Buddhism (~46%) practiced syncretically together.": "Синтоизм (~48%) и буддизм (~46%) гармонично сосуществуют в повседневной жизни.",
  "Mabetlere girmeden Temizuya çeşmesinde eller ve ağız yıkanır; iki kez eğilinip iki kez alkış tutulur.": "Омойте руки и рот в источнике Темидзуя перед входом в святилище; дважды поклонитесь и дважды хлопните в ладоши.",
  "Purify hands and mouth at Temizuya water basin before entering shrines.": "Омойте руки и рот в источнике Темидзуя перед входом в святилище; дважды поклонитесь и дважды хлопните в ладоши.",
