  "Samuray ve Şogunluk çağından Meiji Restorasyonu ile modernleşen ada ülkesi. 2. Dünya Savaşı sonrası teknoloji ve pop kültür devine dönüştü.": "От самураев и сёгунов к эпохе модернизации Мэйдзи. Возродилась как мировой гигант технологий и поп-культуры.",
