  "Mayıs - Haziran ve Eylül - Ekim adalar ve antik kentler için en güzel dönemdir. Temmuz-Ağustos sahiller canlıdır.": "Май-июнь и сентябрь-октябрь идеальны для осмотра достопримечательностей и островов; пик лета очень оживленный, но жаркий.",
  "May - June and September - October for sightseeing and islands; peak summer is lively but hot.": "Май-июнь и сентябрь-октябрь идеальны для осмотра достопримечательностей и островов; пик лета очень оживленный, но жаркий.",
  "Adalar arasında feribotla seyahat edin (Blue Star Ferries / Seajets); biletleri yoğun sezonda önceden ayırtın.": "Путешествуйте между островами на современных паромах; в высокий сезон бронируйте билеты заранее.",
  "Island-hop using modern ferries; book summer island ferry tickets in advance.": "Путешествуйте между островами на современных паромах; в высокий сезон бронируйте билеты заранее.",
  "Yunan Ortodoks Hristiyan (~%90, anayasal milli din), Dinsiz (~%6), Müslüman (~%2, Batı Trakya).": "Греческое православие (~90%), нерелигиозные (~6%), мусульмане (~2%, Западная Фракия).",
  "Greek Orthodox Christian (~90%), Non-religious (~6%), Muslim (~2%, Western Thrace).": "Греческое православие (~90%), нерелигиозные (~6%), мусульмане (~2%, Западная Фракия).",
  "Kiliselerde kadınlar için girişte etek/şal bulunur; ikonalar öpülürken saygı gösterilir.": "У входа в монастыри женщинам предоставляют юбки и платки; перед иконами соблюдайте благоговейное почтение.",
  "Wraps provided at monastery gates for women; quiet reverence before icons.": "У входа в монастыри женщинам предоставляют юбки и платки; перед иконами соблюдайте благоговейное почтение.",
