  "April - June and September - October for pleasant weather.": "С апреля по июнь и с сентября по октябрь — лучшее время для поездки; летом температура на побережье Каспия может достигать 35 °C.",
  "Bakü içinde Bolt ve Uber uygulamaları son derece ucuz ve konforludur; Bakü metrosu için BakiKart kullanılır.": "Приложения Bolt и Uber в Баку очень дешевые и удобные; для поездок на метро используется карта BakiKart.",
  "Bolt and Uber apps are ultra-cheap in Baku; get a BakiKart for the metro.": "Приложения Bolt и Uber в Баку очень дешевые и удобные; для поездок на метро используется карта BakiKart.",
  "Müslüman (~%96, Şii ve Sünni kardeşçe bir arada), Rus Ortodoks ve Musevi toplulukları.": "Мусульмане (~96%, шииты и сунниты гармонично сосуществуют), русская православная и еврейская общины (Красная Слобода).",
  "Muslim (~96%, Shia and Sunni harmoniously coexisting), Russian Orthodox and historic Jewish community (Qırmızı Qəsəbə).": "Мусульмане (~96%, шииты и сунниты гармонично сосуществуют), русская православная и еврейская общины (Красная Слобода).",
  "Dünyanın en seküler Müslüman çoğunluklu ülkelerinden biridir. Camilerde ayakkabı çıkarılır ve örtünme kurallarına uyulur.": "Одна из самых светских стран с мусульманским большинством в мире. При входе в мечети снимают обувь и соблюдают правила скромности в одежде.",
  "One of the most secular Muslim-majority nations. Remove shoes when visiting mosques.": "Одна из самых светских стран с мусульманским большинством в мире. При входе в мечети снимают обувь и соблюдают правила скромности в одежде.",
