  "Azerbaycan Türkçesi (Azərbaycan dili). Türkiye Türkçesi birebir anlaşılır; Rusça ve İngilizce yaygındır.": "Азербайджанский язык. Турецкий полностью понятен без перевода; русский и английский языки широко распространены в Баку.",
  "Azerbaijani. Turkish is mutually intelligible; Russian and English widely understood in Baku.": "Азербайджанский язык. Турецкий полностью понятен без перевода; русский и английский языки широко распространены в Баку.",
  "Bakü’de otellerde ve genç nüfus arasında iyi; Türkiye Türkçesiyle tüm ülkede %100 iletişim kurulabilir.": "Хороший уровень в отелях Баку и среди молодежи; на турецком языке можно свободно общаться по всей стране.",
  "Good in Baku hospitality; Turkish speakers enjoy 100% mutual comprehension across the country.": "Хороший уровень в отелях Баку и среди молодежи; на турецком языке можно свободно общаться по всей стране.",
