  "Bakü’de kart ve temassız POS kabulü %90 oranındadır. Taksi ve pazarlarda nakit Manat (AZN) gerekir.": "В Баку прием карт и бесконтактной оплаты достигает 90 %. В такси и на рынках требуются наличные в азербайджанских манатах (AZN).",
  "Card acceptance is high in Baku (~90%); carry cash Azerbaijani Manat (AZN) for taxis and bazaars.": "В Баку прием карт и бесконтактной оплаты достигает 90 %. В такси и на рынках требуются наличные в азербайджанских манатах (AZN).",
  "Petrol ve doğalgaz, petrokimya, tarım (nar, fındık, pamuk) ve turizm.": "Добыча нефти и газа, нефтехимия, сельское хозяйство (гранаты, фундук, хлопок) и туризм.",
  "Oil and gas extraction, petrochemicals, agriculture (pomegranate, hazelnuts), and transit logistics.": "Добыча нефти и газа, нефтехимия, сельское хозяйство (гранаты, фундук, хлопок) и туризм.",
  "Restoranlarda %10 civarında bahşiş bırakmak nezaket kabul edilir.": "В ресторанах принято оставлять около 10 % чаевых в знак вежливости.",
  "Leaving a 10% tip is customary in full-service dining.": "В ресторанах принято оставлять около 10 % чаевых в знак вежливости.",
  "Kamusal alanlarda kıyafet kurallarına saygı gösterilir (omuz ve dizler kapalı olmalıdır).": "В общественных местах и торговых центрах соблюдается дресс-код (плечи и колени должны быть прикрыты).",
  "Respect modest dress codes in public malls and government buildings (shoulders and knees covered).": "В общественных местах и торговых центрах соблюдается дресс-код (плечи и колени должны быть прикрыты).",
  "Alkol sadece lisanslı otel, restoran ve kulüplerde tüketilebilir; sokakta tüketmek kesinlikle yasaktır.": "Алкоголь разрешен только в лицензированных отелях, ресторанах и клубах; распитие спиртного на улице строго запрещено.",
  "Alcohol is served strictly in licensed venues; public drinking is prohibited.": "Алкоголь разрешен только в лицензированных отелях, ресторанах и клубах; распитие спиртного на улице строго запрещено.",
  "Ramazan ayında gündüz saatlerinde sokakta yiyip içmekten veya sakız çiğnemekten kaçınılmalıdır.": "В священный месяц Рамадан в светлое время суток следует воздерживаться от приема пищи, напитков и курения в общественных местах.",
  "Refrain from eating, drinking, or smoking publicly during Ramadan daylight hours.": "В священный месяц Рамадан в светлое время суток следует воздерживаться от приема пищи, напитков и курения в общественных местах.",
  "İnsanların izinsiz fotoğrafını çekmek ve sosyal medyada paylaşmak yasal olarak yasaktır.": "Фотографировать людей без их согласия и публиковать снимки в социальных сетях запрещено законом.",
  "Taking photos of strangers without their consent is legally restricted.": "Фотографировать людей без их согласия и публиковать снимки в социальных сетях запрещено законом.",
