  "Ultra lüks, fütüristik mimari, dünyanın en güvenli şehirleri, küresel expat topluluğu ve klimalı modern konfor.": "Ультрароскошь, футуристическая архитектура, высочайший уровень безопасности, интернациональное сообщество экспатов и непревзойденный комфорт.",
  "Ultra-luxurious, futuristic skyscrapers, world-class safety, multinational expat community, and glamorous desert adventures.": "Ультрароскошь, футуристическая архитектура, высочайший уровень безопасности, интернациональное сообщество экспатов и непревзойденный комфорт.",
