  "Eid al-Fitr & Eid al-Adha": "Ид аль-Фитр (Ураза-байрам) и Ид аль-Адха (Курбан-байрам)",
  "Moulid el-Nabi (Peygamberin Doğumu şenlikleri)": "Мавлид ан-Наби (празднества в честь дня рождения Пророка с суфийскими песнопениями)",
  "Moulid Festivals (Sufi music celebrations)": "Мавлид ан-Наби (празднества в честь дня рождения Пророка с суфийскими песнопениями)",
