  "Kıpti Asma Kilise (Hanging Church)": "Подвесная коптская церковь (Аль-Муалляка, коптский Каир)",
  "The Hanging Church (Coptic Cairo)": "Подвесная коптская церковь (Аль-Муалляка, коптский Каир)",
