  "Saint Catherine’s Monastery (Mount Sinai)": "Монастырь Святой Екатерины (гора Синай)",
  "Arapça (Mısır lehçesi - Masri, tüm Arap dünyasında diziler sayesinde en çok anlaşılan lehçedir). Turizmde İngilizce yaygındır.": "Египетский арабский язык (масри — самый узнаваемый и популярный диалект арабского мира). В туристической сфере распространен английский.",
  "Egyptian Arabic (Masri - the most widely understood Arabic dialect across the region). English common in tourism.": "Египетский арабский язык (масри — самый узнаваемый и популярный диалект арабского мира). В туристической сфере распространен английский.",
  "Turizm, oteller ve rehberlerde çok iyi; yerel mahallelerde temel düzeydedir.": "Свободное владение среди лицензированных гидов и персонала отелей; базовый уровень на традиционных рынках.",
  "Fluent among licensed Egyptologists and hotel staff; basic in street markets.": "Свободное владение среди лицензированных гидов и персонала отелей; базовый уровень на традиционных рынках.",
  "Selamün Aleyküm": "Ас-саляму алейкум (Мир вам / Традиционное приветствие)",
  "Hello / Peace be upon you": "Ас-саляму алейкум (Мир вам / Традиционное приветствие)",
  "Lütfen / Afedersiniz": "Пожалуйста / Извините",
  "Please / Excuse me": "Пожалуйста / Извините",
  "Firavunlar çağı, piramitler ve hiyerogliflerle 5000 yılı aşkın insanlık tarihinin başlangıcı. İskenderiye, Roma, İslam fetihleri ve Memlükler sonrası modern Mısır, Arap dünyasının kültürel kalbidir.": "Более 5000 лет летописной истории от эпохи фараонов, пирамид и иероглифов. Пройдя через эпохи Птолемеев, Рима, исламских завоеваний и мамлюков, современный Египет остается культурным сердцем арабского мира.",
  "Spanning over 5,000 years of recorded civilization from Pharaohs and Pyramids. Ruled by Ptolemaic dynasties, Romans, and Mamluks, today the cultural anchor of the Arab world.": "Более 5000 лет летописной истории от эпохи фараонов, пирамид и иероглифов. Пройдя через эпохи Птолемеев, Рима, исламских завоеваний и мамлюков, современный Египет остается культурным сердцем арабского мира.",
