  "September - November (crisp autumn foliage) and April - May (cherry blossoms) are ideal.": "Сентябрь — ноябрь (красочный осенний листопад) и апрель — май (цветение сакуры) — лучшее время для посещения.",
  "T-money veya Climate Card kartı alın; KTX hızlı treni ile Seul’den Busan’a 2 saat 15 dakikada geçin.": "Приобретите транспортную карту T-money или Climate Card; скоростной поезд KTX доставит из Сеула в Пусан всего за 2 часа 15 минут.",
  "Buy a T-money transit card; take the KTX bullet train from Seoul to Busan in just 2h 15m.": "Приобретите транспортную карту T-money или Climate Card; скоростной поезд KTX доставит из Сеула в Пусан всего за 2 часа 15 минут.",
  "Dinsiz / Seküler (~%56), Protestan ve Katolik Hristiyan (~%28), Budist (~%15). Konfüçyüsçü ahlak kuralları toplumu derinden şekillendirir.": "Нерелигиозные граждане (~56%), христиане (~28%, протестанты и католики), буддисты (~15%). Конфуцианская этика глубоко определяет нормы поведения.",
  "Non-religious (~56%), Christian (~28%, Protestant & Catholic), Buddhist (~15%). Confucian philosophy guides social morals.": "Нерелигиозные граждане (~56%), христиане (~28%, протестанты и католики), буддисты (~15%). Конфуцианская этика глубоко определяет нормы поведения.",
  "Budist tapınaklarında sessizlik korunmalı; keşişlere hafifçe eğilerek selam verilmelidir.": "В буддийских храмах необходимо соблюдать тишину и приветствовать монахов легким поклоном со сложенными ладонями.",
  "Bowing with hands together in Buddhist temples; respectful quiet on grounds.": "В буддийских храмах необходимо соблюдать тишину и приветствовать монахов легким поклоном со сложенными ладонями.",
