  "Spring (April - June) and Autumn (September - November) offer ideal weather across most states.": "Весна (апрель — июнь) и осень (сентябрь — ноябрь) — наиболее комфортные сезоны для путешествий по всей стране.",
  "Büyük mesafeler için araba kiralayıp ikonik Route 66 rotalarını deneyimleyin; New York’ta ise metro en hızlısıdır.": "Арендуйте автомобиль для масштабных роуд-трипов по национальным паркам и исторической Трассе 66; в Нью-Йорке передвигайтесь исключительно на метро.",
  "Rent a car for epic national park road trips; use the subway exclusively in NYC.": "Арендуйте автомобиль для масштабных роуд-трипов по национальным паркам и исторической Трассе 66; в Нью-Йорке передвигайтесь исключительно на метро.",
  "Protestan (~%40), Katolik (~%21), Musevi, Müslüman, Budist ve hızla artan inançsız/seküler nüfus.": "Протестанты (~40%), католики (~21%), иудеи, мусульмане, буддисты и быстро растущая доля нерелигиозного населения.",
  "Protestant Christian (~40%), Roman Catholic (~21%), Jewish, Muslim, and unaffiliated/secular groups.": "Протестанты (~40%), католики (~21%), иудеи, мусульмане, буддисты и быстро растущая доля нерелигиозного населения.",
  "Kiliselerde ve ibadethanelerde sessiz ve saygılı davranış beklenir; genel toplumda din bireysel bir tercih olarak saygı görür.": "В церквях и молитвенных домах ожидается подобающее тихое поведение; религиозное разнообразие уважается законом и обществом.",
  "Quiet decorum inside chapels and synagogues; religious diversity is protected by constitutional law.": "В церквях и молитвенных домах ожидается подобающее тихое поведение; религиозное разнообразие уважается законом и обществом.",
