  "Gezegendeki en yüksek bisiklet kullanımı, hoşgörülü ve liberal toplum yapısı, kanal kenarı kahveleri ve \"Gezellig\" (samimi/huzurlu) anlar.": "Мировое лидерство по использованию велосипедов, открытое прогрессивное общество, кафе у каналов и атмосфера уюта («Gezellig»).",
