  "April - May for vibrant tulip blooms; June - August for warm canal weather.": "Апрель — май для цветения тюльпанов; июнь — август для теплой летней погоды у каналов.",
  "İlk gün bir bisiklet kiralayın veya OV-chipkaart alarak dünyanın en dakik tren ağıyla şehirden şehre 30 dakikada geçin.": "Возьмите напрокат велосипед в первый же день или приобретите карту OV-chipkaart для удобных 30-минутных поездок на междугородних поездах.",
  "Rent a bicycle or use an OV-chipkaart for seamless 30-minute intercity train connections.": "Возьмите напрокат велосипед в первый же день или приобретите карту OV-chipkaart для удобных 30-минутных поездок на междугородних поездах.",
  "Ağırlıklı seküler ve inançsız (~%55), Katolik (~%20), Protestan (~%15), Müslüman (~%5).": "Преимущественно светское население (~55%), католики (~20%), протестанты (~15%), мусульмане (~5%).",
  "Largely secular/unaffiliated (~55%), Roman Catholic (~20%), Protestant (~15%), Muslim (~5%).": "Преимущественно светское население (~55%), католики (~20%), протестанты (~15%), мусульмане (~5%).",
  "Tarihi kiliselerin çoğu kültür merkezi veya konser salonuna dönüştürülmüştür; saygılı davranış beklenir.": "Многие исторические церкви служат культурными центрами или концертными залами; ожидается уважительное отношение.",
  "Many historic churches serve as cultural venues; quiet architectural respect is expected.": "Многие исторические церкви служат культурными центрами или концертными залами; ожидается уважительное отношение.",
