  "17. Yüzyıl \"Hollanda Altın Çağı\"nda deniz ticareti ve bilimde dünya lideri olan, denizden toprak kazanan (polder sistemi) modern liberal demokrasi.": "Современная либеральная демократия, в XVII веке («Золотой век Голландии») ставшая мировым лидером в морской торговле, науке и мелиорации земель (польдеры).",
  "17th-century Dutch Golden Age pioneered global maritime trade, water engineering (polders), and modern liberal governance.": "Современная либеральная демократия, в XVII веке («Золотой век Голландии») ставшая мировым лидером в морской торговле, науке и мелиорации земель (польдеры).",
