  "Tourism, transit trade, mineral waters and wine exports, business-friendly tax regime.": "Туризм, транзитная торговля, экспорт вин и минеральных вод, реформы для привлечения инвестиций.",
  "Restoranlarda genellikle %10-18 servis ücreti faturaya eklenir. Eklenmemişse %10 bahşiş bırakılır.": "В ресторанах в счет часто включают 10–18% за обслуживание. Если сбор не включен, принято оставлять 10% чаевых.",
  "A 10-18% service fee is often added to restaurant bills. Otherwise, tip 10%.": "В ресторанах в счет часто включают 10–18% за обслуживание. Если сбор не включен, принято оставлять 10% чаевых.",
  "Kahve aceleye getirilmez; Boşnak kahvesi lokum ve sigara eşliğinde saatlerce yudumlanır.": "Кофе не терпит спешки: боснийский кофе пьют не спеша часами с рахат-лукумом.",
  "Coffee is never rushed; Bosnian coffee is savored slowly for hours with Turkish delight.": "Кофе не терпит спешки: боснийский кофе пьют не спеша часами с рахат-лукумом.",
  "Savaş ve etnik siyaset gibi hassas konular yabancılarla hemen açılmaz.": "Не рекомендуется начинать с малознакомыми людьми разговоры на чувствительные темы войны 1990-х годов и этнополитики.",
  "Avoid initiating sensitive conversations about the 1990s war and ethnic politics.": "Не рекомендуется начинать с малознакомыми людьми разговоры на чувствительные темы войны 1990-х годов и этнополитики.",
  "Eve girerken ayakkabılar çıkarılır ve terlik (pape) giyilir.": "При входе в дом всегда снимают обувь; гостям обязательно предлагают домашние тапочки (папе).",
  "Always remove shoes when entering someone’s home; guest slippers (pape) will be offered.": "При входе в дом всегда снимают обувь; гостям обязательно предлагают домашние тапочки (папе).",
  "Misafire ikram edilen yemek veya börek asla geri çevrilmez.": "Отказываться от предложенной домашней еды или пирога считается невежливым.",
  "Refusing home-cooked food is considered impolite.": "Отказываться от предложенной домашней еды или пирога считается невежливым.",
  "Saraybosna Film Festivali (Güneydoğu Avrupa’nın en büyüğü - Ağustos)": "Сараевский кинофестиваль (крупнейший в Юго-Восточной Европе, август)",
  "Sarajevo Film Festival (SFF, August - Largest in SE Europe)": "Сараевский кинофестиваль (крупнейший в Юго-Восточной Европе, август)",
  "Mostar Köprüsü Geleneksel Atlama Yarışları (Temmuz)": "Традиционные соревнования по прыжкам в воду со Старого моста в Мостаре (июль)",
  "Mostar Old Bridge High Diving Competition (July)": "Традиционные соревнования по прыжкам в воду со Старого моста в Мостаре (июль)",
  "Baščaršija Geceleri Kültür Festivali": "Культурный фестиваль «Ночи Башчаршии»",
  "Bascarsija Nights Cultural Festival": "Культурный фестиваль «Ночи Башчаршии»",
  "Osmanlı ve Avusturya-Macaristan mirasının büyüleyici sentezi; içten misafirperverlik, \"Ćejf\" (keyif/huzur) felsefesi.": "Уникальный синтез османского и австро-венгерского наследия: душевное гостеприимство и философия неспешного наслаждения жизнью («Чейф»).",
  "Fascinating blend of Ottoman and Austro-Hungarian heritage; heartfelt warmth and the concept of \"Ćejf\" (pure relaxation).": "Уникальный синтез османского и австро-венгерского наследия: душевное гостеприимство и философия неспешного наслаждения жизнью («Чейф»).",
  "Tarihi Mostar Köprüsü & Neretva Nehri Kanyonu": "Исторический Старый мост в Мостаре и каньон реки Неретва",
  "Stari Most (Old Bridge of Mostar)": "Исторический Старый мост в Мостаре и каньон реки Неретва",
  "Başçarşı & Sebil (Saraybosna)": "Башчаршия и фонтан Себиль (Сараево)",
  "Bascarsija & Sebilj Fountain (Sarajevo)": "Башчаршия и фонтан Себиль (Сараево)",
