  "Sarajevo Tunnel of Hope Museum": "Тоннель надежды (Музей осады Сараево)",
  "Blagaj Alperenler Tekkesi & Buna Nehri Kaynağı": "Благайская текия дервишей и карстовый исток реки Буна",
  "Blagaj Dervish Tekke & Buna Spring": "Благайская текия дервишей и карстовый исток реки Буна",
  "Kravica Şelaleleri (Doğal Yüzme Cenneti)": "Водопады Кравица (природный оазис для купания)",
  "Kravica Waterfalls": "Водопады Кравица (природный оазис для купания)",
  "Počitelj Tarihi Taş Osmanlı Köyü": "Почитель (историческое средневековое османское каменное поселение)",
  "Pocitelj Medieval Ottoman Stone Village": "Почитель (историческое средневековое османское каменное поселение)",
  "Mayıs - Ekim (Şehir gezileri ve kanyon raftingi için); Aralık - Mart (Jahorina ve Bjelašnica kayak merkezleri için).": "Май — октябрь для экскурсий и рафтинга; декабрь — март для горнолыжных курортов Яхорина и Белашница.",
  "May - October for cultural tours and rafting; December - March for Jahorina ski resorts.": "Май — октябрь для экскурсий и рафтинга; декабрь — март для горнолыжных курортов Яхорина и Белашница.",
  "Türk vatandaşları için 90 güne kadar vizesizdir. Saraybosna-Mostar arasındaki tren yolculuğu Avrupa’nın en güzel manzaralı tren rotalarından biridir.": "Безвизовый въезд для граждан Турции до 90 дней. Поездка на поезде между Сараево и Мостаром считается одним из самых живописных железнодорожных маршрутов в Европе.",
  "Visa-free for Turkish citizens. The Sarajevo-Mostar scenic passenger train is ranked among Europe’s most beautiful rail rides.": "Безвизовый въезд для граждан Турции до 90 дней. Поездка на поезде между Сараево и Мостаром считается одним из самых живописных железнодорожных маршрутов в Европе.",
  "Müslüman Boşnaklar (~%51), Ortodoks Sırplar (~%31), Katolik Hırvatlar (~%15). Çok dinli tarihi mozaik.": "Боснийцы-мусульмане (~51%), православные сербы (~31%), католики-хорваты (~15%). Историческая многоконфессиональная мозаика.",
  "Muslim Bosniaks (~51%), Orthodox Christian Serbs (~31%), Roman Catholic Croats (~15%). Historic multifaith mosaic.": "Боснийцы-мусульмане (~51%), православные сербы (~31%), католики-хорваты (~15%). Историческая многоконфессиональная мозаика.",
  "Cami, kilise ve sinagogların yan yana bulunduğu \"Avrupa’nın Kudüs’ü\" olarak anılır; tüm ibadethanelere saygılı kıyafetle girilir.": "Известен как «Иерусалим Европы», где рядом соседствуют мечети, церкви и синагоги; во все храмы требуется скромная одежда.",
  "Known as the \"Jerusalem of Europe\"; modest clothing required when visiting mosques and churches.": "Известен как «Иерусалим Европы», где рядом соседствуют мечети, церкви и синагоги; во все храмы требуется скромная одежда.",
  "Gazi Hüsrev Bey Camii (Saraybosna)": "Мечеть Гази Хусрев-бека (Сараево)",
  "Gazi Husrev-beg Mosque (Sarajevo)": "Мечеть Гази Хусрев-бека (Сараево)",
  "İsa’nın Kutsal Kalbi Katedrali (Saraybosna)": "Собор Святейшего Сердца Иисуса (Сараево)",
  "Sacred Heart Cathedral (Sarajevo)": "Собор Святейшего Сердца Иисуса (Сараево)",
  "Eski Ortodoks Kilisesi": "Старая православная церковь (Сараево)",
  "Old Orthodox Church": "Старая православная церковь (Сараево)",
  "Blagaj Derviş Tekkesi": "Дервишская текия в Благае",
  "Blagaj Dervish Monastery": "Дервишская текия в Благае",
  "Boşnakça, Sırpça, Hırvatça (Birbirini anlayan Güney Slav dilleri). Gençlerde İngilizce yaygındır.": "Боснийский, сербский, хорватский (взаимопонятные южнославянские языки). Молодежь свободно говорит по-английски.",
  "Bosnian, Serbian, and Croatian (Mutually intelligible South Slavic languages). English widely spoken by youth.": "Боснийский, сербский, хорватский (взаимопонятные южнославянские языки). Молодежь свободно говорит по-английски.",
  "Turizm bölgelerinde ve Saraybosna/Mostar’da otel ve restoranlarda yeterlidir.": "Английский достаточен в туристических центрах, отелях и ресторанах Сараево и Мостара.",
  "Good in tourism hubs like Sarajevo and Mostar.": "Английский достаточен в туристических центрах, отелях и ресторанах Сараево и Мостара.",
  "Lütfen / Bir şey değil": "Пожалуйста / Не за что",
  "Please / You’re welcome": "Пожалуйста / Не за что",
  "Ortaçağ Bosna Krallığı’ndan Osmanlı fethine, Avusturya-Macaristan idaresinden Yugoslavya’ya ve 1990’lardaki bağımsızlık mücadelesine uzanan zengin ve çileli tarih.": "Богатая и драматичная история: от средневекового Боснийского королевства и веков османского правления до австро-венгерской эпохи, Югославии и обретения независимости в 1990-х.",
  "From the medieval Kingdom of Bosnia to centuries of Ottoman rule, Austro-Hungarian modernism, Yugoslavia, and sovereign independence.": "Богатая и драматичная история: от средневекового Боснийского королевства и веков османского правления до австро-венгерской эпохи, Югославии и обретения независимости в 1990-х.",
  "1463: Fatih Sultan Mehmed’in Fethi ve Ahidname (Din özgürlüğü fermanı)": "1463: Завоевание султаном Мехмедом II и Ахднаме (указ о свободе вероисповедания)",
  "1463: Ottoman conquest and Ahdname of Milodraz (Declaration of religious freedom)": "1463: Завоевание султаном Мехмедом II и Ахднаме (указ о свободе вероисповедания)",
  "1566: Mimar Hayreddin tarafından Mostar Köprüsü’nün inşası": "1566: Строительство Старого моста в Мостаре зодчим Мимаром Хайреддином",
  "1566: Construction of the Mostar Bridge": "1566: Строительство Старого моста в Мостаре зодчим Мимаром Хайреддином",
  "1914: Franz Ferdinand Suikastı (1. Dünya Savaşı’nın fitili)": "1914: Сараевское убийство эрцгерцога Франца Фердинанда (повод к Первой мировой войне)",
  "1914: Assassination of Archduke Franz Ferdinand in Sarajevo": "1914: Сараевское убийство эрцгерцога Франца Фердинанда (повод к Первой мировой войне)",
