  "Ali Daei & Hadi Saei (Legendary international goalscorer & dual Olympic Taekwondo champion)": "Али Даеи и Хади Саеи (Легендарный футбольный бомбардир-рекордсмен и двукратный олимпийский чемпион по тхэквондо)",
  "Meryem Mirzahani (1977-2017; Matematik dünyasının Nobel'i sayılan Fields Madalyası'nı kazanan ilk kadın matematikçi)": "Марьям Мирзахани (1977–2017; первая женщина, удостоенная Филдсовской премии — высшей математической награды)",
