  "Ham Petrol ve Doğal Gaz Rezervleri (Kanıtlanmış rezervlerde dünyada ilk 3 sırada)": "Запасы сырой нефти и природного газа (Входит в тройку мировых лидеров по доказанным запасам)",
  "Petroleum and Natural Gas Reserves (Top 3 proven global energy reserves)": "Запасы сырой нефти и природного газа (Входит в тройку мировых лидеров по доказанным запасам)",
