  "DTV e-vizesi online alınır; harç sadece ~10.000 THB (~300 $). Ayrıca Türk pasaportuna 30 gün vizesiz giriş (TDAC ile) hakkı mevcuttur.": "Онлайн-заявка на eVisa DTV (пошлина ~10 000 THB / ~300 $). Также доступен безвизовый въезд на 30 дней.",
